def nice_tick(limit_min):
    for tick in (1, 2, 5, 10, 15, 20, 30, 60):
        if limit_min / tick <= 4.01:
            return tick
    return 60


def direct_labels(ax, limit, ends):
    same = {}
    for y, k in ends:
        same.setdefault(round(y), []).append(k)
    labels = sorted(((y, ", ".join(str(k) for k in sorted(ks))) for y, ks in same.items()), key=lambda e: e[0])
    low, high = ax.get_ylim()
    gap = 0.085 * (high - low)
    placed = []
    for y, text in labels:
        placed.append(max(y, placed[-1] + gap) if placed else y)
    for (y, text), at in zip(labels, placed):
        ax.annotate(text, xy=(limit, at), xycoords="data", xytext=(4, 0), textcoords="offset points", va="center", ha="left", fontsize=7, color=INK2, annotation_clip=False)


def short(case):
    return case.split("-", 1)[1]


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "scaling-4x3")
    by_system = {s: [p for p in PANELS if p[0] == s] for s, _ in SYSTEMS}
    rows_n = max(len(v) for v in by_system.values())
    plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 7.5, "axes.edgecolor": AXIS, "axes.linewidth": 0.7, "xtick.color": INK2, "ytick.color": INK2, "axes.labelcolor": INK2, "pdf.fonttype": 42,
                         "figure.facecolor": SURFACE, "axes.facecolor": SURFACE, "savefig.facecolor": SURFACE})
    fig, axes = plt.subplots(rows_n, len(SYSTEMS), figsize=(9.6, 1.9 * rows_n), constrained_layout=True, squeeze=False)
    fig.set_constrained_layout_pads(w_pad=0.09, h_pad=0.05)
    handles = {}
    for col, (system, title) in enumerate(SYSTEMS):
        for row, (_, case, window_min) in enumerate(by_system[system]):
            ax = axes[row][col]
            limit_s = window_min * 60.0
            xs = np.append(np.arange(0, limit_s, STEP_S), limit_s) / 60.0
            ax.set_title(short(case) if row else "%s\n%s" % (title, short(case)), loc="left", fontsize=8, color=INK, pad=3)
            ends = []
            for k in MACHINES:
                ys = DATA[case].get(k)
                if ys is None:
                    continue
                ys = np.array(ys, dtype=float)
                assert len(ys) == len(xs), (case, k, len(ys), len(xs))
                line, = ax.plot(xs, ys, color=RAMP[k], linewidth=1.5, solid_joinstyle="round", solid_capstyle="round", zorder=2 + k / 10.0)
                handles[k] = line
                ends.append((float(ys[-1]), k))
            ax.set_xlim(0, window_min)
            ax.set_ylim(bottom=0)
            ax.margins(y=0.06)
            ax.yaxis.set_major_locator(MaxNLocator(nbins=4, integer=True, min_n_ticks=3))
            tick = nice_tick(window_min)
            ax.set_xticks(np.arange(0, window_min + 0.01, tick))
            ax.grid(True, axis="y", color=GRID, linewidth=0.6)
            ax.set_axisbelow(True)
            for side in ("top", "right", "left"):
                ax.spines[side].set_visible(False)
            ax.tick_params(length=0, pad=3)
            if ends:
                direct_labels(ax, window_min, ends)
    fig.supxlabel("Exploration time (minutes)", fontsize=8.5, color=INK2)
    fig.supylabel("New unique region paths", fontsize=8.5, color=INK2)
    fig.legend([handles[k] for k in sorted(handles)], ["%d machine%s" % (k, "" if k == 1 else "s") for k in sorted(handles)], loc="lower right", bbox_to_anchor=(1.0, 1.0), ncol=len(handles), frameon=False, fontsize=8, labelcolor=INK2, handlelength=1.8, columnspacing=1.4)
    fig.savefig(out + ".pdf", bbox_inches="tight", pad_inches=0.04)
    fig.savefig(out + ".png", dpi=220, bbox_inches="tight", pad_inches=0.04)
    print("wrote", out + ".pdf", "and", out + ".png:", sum(len(v) for v in DATA.values()), "lines in", len(PANELS), "panels")


if __name__ == "__main__":
    main()
